// Regenerates src/cli/templates.generated.ts from the reference projects, so
// `kadam new` ships them inside the package. Run: node scripts/generate-templates.mjs
// test/f7-new.test.mjs fails when the generated file is out of date.
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";

const SOURCES = {
  minimal: null,
  blog: "examples/reference/blog",
  dashboard: "examples/reference/dashboard",
  docs: "examples/reference/docs",
  marketing: "examples/reference/marketing",
  shop: "examples/reference/shop",
  server: "test/fixtures/server-shop",
};
const DESCRIPTIONS = {
  minimal: "One page with a heading, a paragraph and a button",
  blog: "Posts from a data file, Markdown documents and a page per post",
  dashboard: "An overview page with metric cards and a table",
  docs: "Two documentation pages with a sidebar, navigation and a table",
  marketing: "A landing page and a pricing page with a comparison table",
  shop: "Products loaded at run time, with filters and paging",
  server: "Pages that load from and send forms to a kadam 0.2 server module",
};
const MINIMAL = {
  "kadam.json": `${JSON.stringify({ kadam: "0.3", name: "my-site", pages: [{ source: "pages/home.kdm", route: "/" }] }, null, 2)}\n`,
  "pages/home.kdm": `kadam 0.3

page "Home" {
    intro {
        a section
        it has 64px padding
        it has 16px gap between children
        welcome {
            a main heading
            the text says "Hello from Kadam"
        }
        lead {
            a paragraph
            the text says "Edit pages/home.kdm and the page reloads."
        }
        learnMore {
            a button
            the text says "Read the guide"
            when clicked, open "https://example.com" in a new tab
        }
    }
}
`,
};

function walk(root, dir = root, out = {}) {
  for (const name of readdirSync(dir).sort()) {
    const path = join(dir, name);
    if (name === "dist" || name.startsWith(".")) continue;
    if (statSync(path).isDirectory()) walk(root, path, out);
    else out[relative(root, path).split("\\").join("/")] = readFileSync(path, "utf8");
  }
  return out;
}

const templates = Object.entries(SOURCES).map(([name, source]) => ({
  name,
  description: DESCRIPTIONS[name],
  files: source === null ? MINIMAL : walk(source),
}));
const body = [
  "// Generated by scripts/generate-templates.mjs from the reference projects. Do not edit.",
  "",
  "export interface ProjectTemplate {",
  "  readonly name: string;",
  "  readonly description: string;",
  "  readonly files: Readonly<Record<string, string>>;",
  "}",
  "",
  `export const PROJECT_TEMPLATES: readonly ProjectTemplate[] = ${JSON.stringify(templates, null, 2)};`,
  "",
].join("\n");
writeFileSync("src/cli/templates.generated.ts", body);
console.log(`wrote ${templates.length} templates`);
